export function findTargetPair(nums, target) {
  const seen = new Map();
  for (let right = 0; right < nums.length; right++) {
    const complement = target - nums[right];
    if (seen.has(complement)) return [seen.get(complement), right];
    if (!seen.has(nums[right])) seen.set(nums[right], right);
  }
  return [];
}
